//! Block-Max WAND workloads with useful and deliberately unhelpful bounds.

use criterion::{black_box, criterion_group, criterion_main, BenchmarkId, Criterion};
use postings::raw::{write_u64_u32_segment, RawDocument, RawSegment, RawSegmentFile};

const DOCS: u32 = 30_000;

#[derive(Clone, Copy)]
enum Pruning {
    None,
    Moderate,
    Strong,
}

impl Pruning {
    fn name(self) -> &'static str {
        match self {
            Self::None => "none",
            Self::Moderate => "moderate",
            Self::Strong => "strong",
        }
    }

    fn weight(self, doc_id: u32, term_id: u64) -> u32 {
        match self {
            Self::None => 1 + ((doc_id as u64 + term_id) % 7) as u32,
            Self::Moderate if doc_id < 1_000 => 10_000 + doc_id % 17,
            Self::Strong if doc_id < 10 => 1_000_000,
            Self::Moderate | Self::Strong => 1,
        }
    }
}

fn build_fixture(
    width: usize,
    pruning: Pruning,
    staggered: bool,
) -> (tempfile::TempDir, RawSegmentFile, Vec<(u64, f32)>) {
    let weighted_docs: Vec<Vec<_>> = (0..DOCS)
        .map(|doc_id| {
            (0..width as u64)
                .filter_map(|term_id| {
                    let present = !staggered
                        || (doc_id + term_id as u32 * 37) % (97 + term_id as u32 % 11) != 0;
                    present.then_some((term_id, pruning.weight(doc_id, term_id)))
                })
                .collect()
        })
        .collect();
    let docs: Vec<_> = weighted_docs
        .iter()
        .enumerate()
        .map(|(doc_id, terms)| RawDocument::new(doc_id as u32, terms))
        .collect();
    let bytes = write_u64_u32_segment(&docs).unwrap();
    let exhaustive = RawSegment::open(&bytes).unwrap();
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("bmw-matrix.raw");
    std::fs::write(&path, &bytes).unwrap();
    let mut file = RawSegmentFile::open(path).unwrap();
    let query: Vec<_> = (0..width as u64).map(|term_id| (term_id, 1.0)).collect();

    for k in [10, 100, 1_000] {
        assert_eq!(
            file.top_k_weighted_u32(&query, k).unwrap(),
            exhaustive.top_k_weighted_u32(&query, k).unwrap()
        );
    }
    (dir, file, query)
}

fn bench_bmw_matrix(c: &mut Criterion) {
    let mut group = c.benchmark_group("raw_file_bmw_matrix");
    group.sample_size(20);

    for staggered in [false, true] {
        for pruning in [Pruning::None, Pruning::Moderate, Pruning::Strong] {
            for width in [8usize, 16, 32] {
                let (_dir, mut file, query) = build_fixture(width, pruning, staggered);
                for k in [10usize, 100, 1_000] {
                    let case = format!(
                        "{}_{}_w{width}_k{k}",
                        if staggered { "staggered" } else { "equal" },
                        pruning.name()
                    );
                    group.bench_with_input(BenchmarkId::from_parameter(case), &k, |b, &k| {
                        b.iter(|| {
                            black_box(
                                file.top_k_weighted_u32(black_box(&query), black_box(k))
                                    .unwrap(),
                            );
                        });
                    });
                }
            }
        }
    }
    group.finish();
}

criterion_group!(benches, bench_bmw_matrix);
criterion_main!(benches);

//! Focused Criterion target for large single-term file-backed raw top-k search.

use criterion::{black_box, criterion_group, criterion_main, Criterion};
use postings::raw::{
    write_u64_u32_segment_from_term_postings_seekable_to, RawSegmentFile, RawTermId,
    RawTermPostingList,
};
use std::fs::File;

const DOCS: usize = 600_000;
const TERM: RawTermId = 42;
const HIGH_BLOCK_DOCS: u32 = 128;

type SingleLargeFixture = (tempfile::TempDir, RawSegmentFile, Vec<(RawTermId, f32)>);

fn build_single_large_filtered_fixture() -> SingleLargeFixture {
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("single-large.raw");
    let document_lengths: Vec<_> = (0..DOCS as u32).map(|doc_id| (doc_id, 1)).collect();
    let postings: Vec<_> = (0..DOCS as u32)
        .map(|doc_id| {
            let weight = if doc_id < HIGH_BLOCK_DOCS {
                10_000 - (doc_id % 17)
            } else {
                1
            };
            (doc_id, weight)
        })
        .collect();
    let terms = [RawTermPostingList::new(TERM, &postings)];
    let mut file = File::create(&path).unwrap();
    write_u64_u32_segment_from_term_postings_seekable_to(&document_lengths, &terms, &mut file)
        .unwrap();

    (dir, RawSegmentFile::open(path).unwrap(), vec![(TERM, 1.0)])
}

fn bench_single_large(c: &mut Criterion) {
    let (_dir, mut segment, query_terms) = build_single_large_filtered_fixture();
    assert!(segment.posting_blocks(TERM).unwrap().len() > 1);
    let result = segment
        .top_k_weighted_u32_filtered(&query_terms, 10, |doc_id| doc_id % 7 != 0)
        .unwrap();
    assert_eq!(result.len(), 10);
    assert!(result
        .iter()
        .all(|(doc_id, score)| *doc_id < HIGH_BLOCK_DOCS && *score > 9_900.0));

    let mut group = c.benchmark_group("raw_file_single_large");
    group.bench_function("filtered", |b| {
        b.iter(|| {
            black_box(
                segment
                    .top_k_weighted_u32_filtered(
                        black_box(query_terms.as_slice()),
                        black_box(10),
                        |doc_id| doc_id % 7 != 0,
                    )
                    .unwrap(),
            );
        });
    });
    group.finish();
}

criterion_group!(benches, bench_single_large);
criterion_main!(benches);

//! Focused Criterion target for profiling file-backed raw top-k search.
//!
//! `benches/query.rs` covers the broad query suite. This target keeps filtered
//! raw multi-file timings and profiles from paying unrelated query-suite setup.

use criterion::{black_box, criterion_group, criterion_main, Criterion};
use postings::raw::{
    top_k_weighted_u32_files, top_k_weighted_u32_files_and_index,
    top_k_weighted_u32_files_filtered, top_k_weighted_u32_files_with_stats, write_u64_u32_segment,
    RawDocument, RawSegmentFile, RawTermId,
};
use postings::PostingsIndex;
use std::collections::BTreeMap;

const N_DOCS: usize = 50_000;
const VOCAB_SIZE: usize = 10_000;
const TERMS_PER_DOC: usize = 100;
const SEGMENTS: usize = 64;
const PARTITIONED_DOCS_PER_SEGMENT: usize = 512;
const PARTITIONED_VOCAB_PER_SEGMENT: usize = 512;
const PARTITIONED_TERMS_PER_DOC: usize = 32;
const LIVE_PRUNE_DOCS_PER_SEGMENT: usize = 256;
const LIVE_PRUNE_DOC_BASE: u32 = 1_000_000;
const BLOCK_WAND_DOCS: usize = 600_000;
const BLOCK_WAND_TERMS: usize = 16;
const BLOCK_WAND_LOW_PRUNING_DOCS: usize = 100_000;

type WeightedDocs = Vec<Vec<(RawTermId, u32)>>;
type LivePruneFixture = (
    tempfile::TempDir,
    Vec<RawSegmentFile>,
    PostingsIndex<RawTermId, u32>,
    Vec<(RawTermId, f32)>,
);

fn zipf_sample(rng: &mut u64, vocab_size: usize) -> usize {
    *rng ^= *rng << 13;
    *rng ^= *rng >> 7;
    *rng ^= *rng << 17;
    let u = (*rng as f64) / (u64::MAX as f64);
    let n = vocab_size as f64;
    let k = (u * (n + 1.0_f64).ln()).exp() - 1.0;
    (k as usize).min(vocab_size - 1)
}

fn build_weighted_docs() -> (WeightedDocs, Vec<u32>) {
    let mut docs = Vec::with_capacity(N_DOCS);
    let mut dfs = vec![0u32; VOCAB_SIZE];
    let mut rng = 0xdeadbeef_cafebabe;

    for _ in 0..N_DOCS {
        let mut counts = BTreeMap::new();
        for _ in 0..TERMS_PER_DOC {
            let term_id = zipf_sample(&mut rng, VOCAB_SIZE) as RawTermId;
            *counts.entry(term_id).or_insert(0u32) += 1;
        }
        for &term_id in counts.keys() {
            dfs[term_id as usize] += 1;
        }
        docs.push(counts.into_iter().collect());
    }

    (docs, dfs)
}

fn raw_segment_bytes_from_docs(
    weighted_docs: &[Vec<(RawTermId, u32)>],
    start_doc_id: u32,
) -> Vec<u8> {
    let raw_docs: Vec<_> = weighted_docs
        .iter()
        .enumerate()
        .map(|(offset, terms)| RawDocument::new(start_doc_id + offset as u32, terms))
        .collect();
    write_u64_u32_segment(&raw_docs).unwrap()
}

fn build_fixture() -> (
    tempfile::TempDir,
    Vec<RawSegmentFile>,
    Vec<(RawTermId, f32)>,
) {
    let (weighted_docs, dfs) = build_weighted_docs();
    let weighted_terms: Vec<_> = dfs
        .iter()
        .enumerate()
        .filter(|(_, df)| **df >= 10)
        .take(5)
        .enumerate()
        .map(|(i, (term_id, _))| (term_id as RawTermId, 1.0 + (i as f32 * 0.1)))
        .collect();

    let dir = tempfile::tempdir().unwrap();
    let chunk_size = N_DOCS.div_ceil(SEGMENTS);
    let mut segments = Vec::new();
    for (chunk_index, chunk) in weighted_docs.chunks(chunk_size).enumerate() {
        let start_doc_id = (chunk_index * chunk_size) as u32;
        let path = dir.path().join(format!("numeric-{chunk_index}.raw"));
        std::fs::write(&path, raw_segment_bytes_from_docs(chunk, start_doc_id)).unwrap();
        segments.push(RawSegmentFile::open(path).unwrap());
    }

    (dir, segments, weighted_terms)
}

fn build_partitioned_fixture() -> (
    tempfile::TempDir,
    Vec<RawSegmentFile>,
    Vec<(RawTermId, f32)>,
) {
    let dir = tempfile::tempdir().unwrap();
    let mut segments = Vec::new();

    for segment_index in 0..SEGMENTS {
        let term_base = (segment_index * PARTITIONED_VOCAB_PER_SEGMENT) as RawTermId;
        let doc_base = (segment_index * PARTITIONED_DOCS_PER_SEGMENT) as u32;
        let mut docs = Vec::with_capacity(PARTITIONED_DOCS_PER_SEGMENT);

        for doc_offset in 0..PARTITIONED_DOCS_PER_SEGMENT {
            let mut terms = BTreeMap::new();
            for term_offset in 0..PARTITIONED_TERMS_PER_DOC {
                let local_term =
                    (doc_offset * 37 + term_offset * 17) % PARTITIONED_VOCAB_PER_SEGMENT;
                let weight = 1 + ((doc_offset + term_offset + segment_index) % 7) as u32;
                terms.insert(term_base + local_term as RawTermId, weight);
            }
            docs.push(terms.into_iter().collect());
        }

        let path = dir.path().join(format!("partitioned-{segment_index}.raw"));
        std::fs::write(&path, raw_segment_bytes_from_docs(&docs, doc_base)).unwrap();
        segments.push(RawSegmentFile::open(path).unwrap());
    }

    let weighted_terms = (0..5)
        .map(|i| (i as RawTermId, 1.0 + (i as f32 * 0.1)))
        .collect();
    (dir, segments, weighted_terms)
}

fn build_live_prune_fixture() -> LivePruneFixture {
    let dir = tempfile::tempdir().unwrap();
    let mut segments = Vec::new();

    for segment_index in 0..SEGMENTS {
        let doc_base = (segment_index * LIVE_PRUNE_DOCS_PER_SEGMENT) as u32;
        let docs: Vec<_> = (0..LIVE_PRUNE_DOCS_PER_SEGMENT)
            .map(|doc_offset| {
                let weight = 1 + ((segment_index + doc_offset) % 3) as u32;
                vec![(0, weight)]
            })
            .collect();
        let path = dir.path().join(format!("live-prune-{segment_index}.raw"));
        std::fs::write(&path, raw_segment_bytes_from_docs(&docs, doc_base)).unwrap();
        segments.push(RawSegmentFile::open(path).unwrap());
    }

    let mut live = PostingsIndex::new();
    for doc_offset in 0..16u32 {
        live.add_weighted_document(LIVE_PRUNE_DOC_BASE + doc_offset, &[(0, 10_000)])
            .unwrap();
    }

    (dir, segments, live, vec![(0, 1.0)])
}

fn build_block_wand_fixture() -> (tempfile::TempDir, RawSegmentFile, Vec<(RawTermId, f32)>) {
    let docs: WeightedDocs = (0..BLOCK_WAND_DOCS)
        .map(|doc_id| {
            let weight = if doc_id < 10 { 1_000_000 } else { 1 };
            (0..BLOCK_WAND_TERMS)
                .map(|term_id| (term_id as RawTermId, weight))
                .collect()
        })
        .collect();
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("block-wand.raw");
    std::fs::write(&path, raw_segment_bytes_from_docs(&docs, 0)).unwrap();
    let query = (0..BLOCK_WAND_TERMS)
        .map(|term_id| (term_id as RawTermId, 1.0))
        .collect();
    (dir, RawSegmentFile::open(path).unwrap(), query)
}

fn build_block_wand_low_pruning_fixture(
) -> (tempfile::TempDir, RawSegmentFile, Vec<(RawTermId, f32)>) {
    let docs: WeightedDocs = (0..BLOCK_WAND_LOW_PRUNING_DOCS)
        .map(|doc_id| {
            (0..BLOCK_WAND_TERMS)
                .map(|term_id| (term_id as RawTermId, 1 + ((doc_id + term_id) % 7) as u32))
                .collect()
        })
        .collect();
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("block-wand-low-pruning.raw");
    std::fs::write(&path, raw_segment_bytes_from_docs(&docs, 0)).unwrap();
    let query = (0..BLOCK_WAND_TERMS)
        .map(|term_id| (term_id as RawTermId, 1.0))
        .collect();
    (dir, RawSegmentFile::open(path).unwrap(), query)
}

fn bench_multi_file_top_k(c: &mut Criterion) {
    let (_dir, mut segments, weighted_terms) = build_fixture();
    let (_partitioned_dir, mut partitioned_segments, partitioned_weighted_terms) =
        build_partitioned_fixture();
    let (_live_prune_dir, mut live_prune_segments, live_prune_index, live_prune_terms) =
        build_live_prune_fixture();
    let (_block_wand_dir, mut block_wand_segment, block_wand_terms) = build_block_wand_fixture();
    let (
        _block_wand_low_pruning_dir,
        mut block_wand_low_pruning_segment,
        block_wand_low_pruning_terms,
    ) = build_block_wand_low_pruning_fixture();

    {
        let mut segment_refs: Vec<_> = partitioned_segments.iter_mut().collect();
        let result =
            top_k_weighted_u32_files_with_stats(&mut segment_refs, &partitioned_weighted_terms, 10)
                .unwrap();
        assert_eq!(result.stats.segments_seen, SEGMENTS);
        assert_eq!(result.stats.segments_scored, 1);
        assert_eq!(result.stats.segments_pruned, SEGMENTS - 1);
    }
    {
        let mut segment_refs: Vec<_> = live_prune_segments.iter_mut().collect();
        let result = top_k_weighted_u32_files_and_index(
