                .unwrap(),
            );
        });
    });
    group.bench_function("multi_64_with_stats", |b| {
        let mut segment_refs: Vec<_> = segments.iter_mut().collect();
        b.iter(|| {
            black_box(
                top_k_weighted_u32_files_with_stats(
                    black_box(segment_refs.as_mut_slice()),
